"""
    Calc metrics per image
    :param tp:
    :param pred_len:
    :param gt_len:
    :param labels_num:
    :return:
    """
def metrics(tp: Any, pred_len: Any, gt_len: Any, labels_num: Any) -> object {
    fn = gt_len - tp;
    fp = pred_len - tp;
    tn = labels_num - tp - fn - fp;
    if (tp == 0) {
        (recall, precision, f1) = (0, 0, 0);
    } else {
        recall = tp / gt_len;
        precision = tp / pred_len;
        f1 = (2 * recall * precision) / (recall + precision);
    }
    accuracy = tp / ((gt_len + pred_len) - tp);
    accuracy_balanced = ((tp / (tp + fn)) + (tn / (tn + fp))) / 2;
    return (recall, precision, f1, accuracy, accuracy_balanced);
}

"""Returns dictionary-record for from history_list_of_dicts.
    """
def history_dict_for_file(listdicts: Any, fname: Any) -> object {
    if (listdicts is None) {
        return None;
    }
    for d in listdicts {
        v = d.get('file', None);
        if (v == None) {
            continue;
        }
        if (v == fname) {
            return d;
        }
    }
    return None;
}

"""
    Return the value for a udev key.

    The `key` parameter is a lower case text joined by dots. For
    example, 'e.id_bus' will represent the key for
    `udev_info['E']['ID_BUS']`.

    """
def _udev(udev_info: Any, key: Any) -> object {
    (k, _, r) = key.partition(".");
    if not k {
        return udev_info;
    }
    if not isinstance(udev_info, `dict) {
        return "n/a";
    }
    if not r {
        return udev_info.get(k.upper(), "n/a");
    }
    return _udev(udev_info.get(k.upper(), {}), r);
}

